    long long R, C, S;
    cin >> R >> C >> S;

    // 小规模特殊构造
    if (R <= 2 && C <= 2 && R * C <= S) {
        for (int i = 1; i <= R; ++i) {
            if (i < R) {
                for (int j = 0; j < C; ++j)
                    cout << 1 << ' ';
            } else {
                for (int j = 0; j < C - 1; ++j)
                    cout << 1 << ' ';
                cout << S - R * C + 1 << ' ';
            }
            cout << '\n';
        }
        return 0;
    }

    // 一般情况
    if ((2 * S) % (R * C) != 0) {
        cout << -1 << '\n';
        return 0;
    }

    long long X = (2 * S) / (R * C);
    long long a1 = -1, d = -1;

    if (X >= 2 && X % 2 == 0) {
        d = 0;
        a1 = X / 2;
    } else if (R > 1) {
        long long tmp = X - (R - 1);
        if (tmp >= 2 && tmp % 2 == 0) {
            d = 1;
            a1 = tmp / 2;
        } else {
            tmp = X - 2 * (R - 1);
            if (tmp >= 2 && tmp % 2 == 0) {
                d = 2;
                a1 = tmp / 2;
            }
        }
    }

    if (a1 == -1) {
        cout << -1 << '\n';
        return 0;
    }

    for (int i = 0; i < R; ++i) {
        long long val = a1 + i * d;
        for (int j = 0; j < C; ++j) {
            cout << val << (j < C - 1 ? ' ' : '\n');
        }
    }

    return 0;
}
